INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-216',unit_id,'quiz-topic-neuro-ap1','Que acidente é o mais evidente no pavimento da fossa craniana posterior?',NULL,'É limitada anteriormente pelo dorso da sela, faces posteriores do corpo do esfenóide e parte basilar ou clival do occipital; posteriormente pela parte escamosa do occipital; e lateralmente pelas porções petrosa e mastoideia dos temporais e pelas partes laterais ou condilares do occipital. O acidente mais evidente do pavimento da fossa posterior é o <strong>buraco magno</strong>. O bulbo deixa a cavidade craniana através deste buraco para se continuar com a medula espinhal.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
