INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-217',unit_id,'quiz-topic-neuro-ap1','Que superfície inclinada se estende da sela turca ao buraco magno?',NULL,'Quando as tonsilas cerebelosas descem anormalmente através do buraco magno podem comprimir o bulbo neste nível, situação designada herniação tonsilar ou malformação de Chiari. O <strong>clivus</strong> é uma superfície inclinada que se estende da sela turca ao buraco magno e é formada sucessivamente pelo dorso da sela, parte posterior do corpo do esfenóide e parte basilar ou clival do occipital. A sincondrose esfenooccipital é visível no clivus da criança em crescimento, mas não no adulto.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-217-answer','quiz-neuro-ap1-217','Clivus',1,1);
