INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-218-incorrect','quiz-neuro-ap1-218','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-219',unit_id,'quiz-topic-neuro-ap1','Que fissura separa o clivus da porção petrosa do temporal?',NULL,'De cada lado, o clivus é separado da porção petrosa do temporal pela <strong>fissura petro-occipital</strong> ou petroclival, preenchida por uma fina lâmina cartilagínea e estendida do buraco lácero na face extracraniana ou do seio cavernoso na face intracraniana até ao buraco jugular. Os bordos intracranianos desta fissura são sulcados pelo seio petroso inferior.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-219-answer','quiz-neuro-ap1-219','Fissura petro-occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-219-incorrect','quiz-neuro-ap1-219','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-220',unit_id,'quiz-topic-neuro-ap1','Que seio sulca os bordos intracranianos da fissura petro-occipital?',NULL,'De cada lado, o clivus é separado da porção petrosa do temporal pela fissura petro-occipital ou petroclival. <strong>Os bordos intracranianos desta fissura são sulcados pelo seio petroso inferior</strong>.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-220-answer','quiz-neuro-ap1-220','Seio petroso inferior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-220-incorrect','quiz-neuro-ap1-220','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-221',unit_id,'quiz-topic-neuro-ap1','Entre que ossos se forma o buraco jugular?',NULL,'O buraco jugular é uma grande abertura entre os ossos <strong>temporal e occipital</strong>, na extremidade posterior da fissura petro-occipital, superior e lateralmente ao buraco magno. O bordo inferior é liso e formado pela parte lateral do occipital; o bordo superior é agudo e irregular e pertence à porção petrosa do temporal.<p><small>Gray’s Anatomy, 42.ª ed., pp. 567–568.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-221-answer','quiz-neuro-ap1-221','Temporal e occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-221-incorrect','quiz-neuro-ap1-221','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-222',unit_id,'quiz-topic-neuro-ap1','Que porção do buraco jugular recebe o seio sigmóide?',NULL,'O bordo inferior é liso e formado pela parte lateral do occipital; o bordo superior é agudo e irregular e pertence à porção petrosa do temporal. Uma incisura, a apófise intrajugular, divide o buraco numa grande porção posterolateral, a <strong>parte sigmóide</strong>, que recebe o seio sigmóide, e numa pequena porção anteromedial, a parte petrosa, que recebe o seio petroso inferior. Os nervos acessório, vago e glossofaríngeo passam medialmente à apófise intrajugular, entre a parte petrosa, onde o seio petroso inferior é acompanhado por um ramo meníngeo da artéria faríngea ascendente, e a parte sigmóide, que contém o seio sigmóide acompanhado por um ramo meníngeo da artéria occipital.<p><small>Gray’s Anatomy, 42.ª ed., pp. 567–568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-222-answer','quiz-neuro-ap1-222','Parte sigmóide',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-222-incorrect','quiz-neuro-ap1-222','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-223',unit_id,'quiz-topic-neuro-ap1','Que porção do buraco jugular recebe o seio petroso inferior?',NULL,'O bordo inferior é liso e formado pela parte lateral do occipital; o bordo superior é agudo e irregular e pertence à porção petrosa do temporal. Uma incisura, a apófise intrajugular, divide o buraco numa grande porção posterolateral, a parte sigmóide, que recebe o seio sigmóide, e numa pequena porção anteromedial, a <strong>parte petrosa</strong>, que recebe o seio petroso inferior. Os nervos acessório, vago e glossofaríngeo passam medialmente à apófise intrajugular, entre a parte petrosa, onde o seio petroso inferior é acompanhado por um ramo meníngeo da artéria faríngea ascendente, e a parte sigmóide, que contém o seio sigmóide acompanhado por um ramo meníngeo da artéria occipital.<p><small>Gray’s Anatomy, 42.ª ed., pp. 567–568.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
