INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-224',unit_id,'quiz-topic-neuro-ap1','Que estrutura divide as partes sigmóide e petrosa do buraco jugular?',NULL,'O bordo inferior é liso e formado pela parte lateral do occipital; o bordo superior é agudo e irregular e pertence à porção petrosa do temporal. Uma incisura, a <strong>apófise intrajugular</strong>, divide o buraco numa grande porção posterolateral, a parte sigmóide, que recebe o seio sigmóide, e numa pequena porção anteromedial, a parte petrosa, que recebe o seio petroso inferior. Os nervos acessório, vago e glossofaríngeo passam medialmente à apófise intrajugular, entre a parte petrosa, onde o seio petroso inferior é acompanhado por um ramo meníngeo da artéria faríngea ascendente, e a parte sigmóide, que contém o seio sigmóide acompanhado por um ramo meníngeo da artéria occipital.<p><small>Gray’s Anatomy, 42.ª ed., pp. 567–568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
