INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-227-incorrect','quiz-neuro-ap1-227','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-228',unit_id,'quiz-topic-neuro-ap1','Onde se situa o canal do hipoglosso relativamente ao tubérculo jugular?',NULL,'Os nervos acessório, vago e glossofaríngeo cruzam a porção posterior do tubérculo no trajeto para o buraco jugular. O canal do nervo hipoglosso situa-se imediatamente abaixo do tubérculo jugular, superiormente ao côndilo occipital e medial e <strong>inferiormente</strong> ao bordo inferior do buraco jugular. Transmite o nervo hipoglosso e o seu ramo recorrente, um ramo meníngeo da artéria faríngea ascendente e uma veia emissária que liga o plexo basilar intracraniano à veia jugular interna extracraniana.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
