INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-231',unit_id,'quiz-topic-neuro-ap1','Que vasos atravessam o meato acústico interno?',NULL,'A face posterior da porção petrosa do temporal forma grande parte da parede anterolateral da fossa posterior. Contém o meato acústico interno, situado anterossuperiormente ao buraco jugular, que transmite os nervos facial e vestibulococlear, o nervo intermédio e os <strong>vasos labirínticos</strong>. Posteriormente, entre o meato acústico interno e a abertura do aqueduto do vestíbulo, existe uma pequena fossa subarqueada revestida por dura-máter.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
