INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-232',unit_id,'quiz-topic-neuro-ap1','Que sulco da porção mastoideia aloja o seio sigmóide?',NULL,'A porção mastoideia do temporal situa-se posteriormente à porção petrosa na parede lateral da fossa posterior. Anteriormente apresenta um amplo <strong>sulco sigmóide</strong> que segue primeiro para a frente e para baixo, depois inferior e medialmente e finalmente anteriormente até ao buraco jugular; contém o seio sigmóide. Superiormente, quando o sulco alcança o ângulo mastoideu do parietal, continua-se com o sulco do seio transverso, cruza a sutura parietomastoideia e desce atrás do antro mastoideu.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-232-answer','quiz-neuro-ap1-232','Sulco sigmóide',1,1);
