INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-233',unit_id,'quiz-topic-neuro-ap1','Que crista mediana da fossa posterior dá inserção à foice do cerebelo?',NULL,'O sulco sigmóide direito é habitualmente maior do que o esquerdo. A parte escamosa do occipital apresenta uma <strong>crista occipital interna</strong> mediana que se estende posteriormente do buraco magno até à protuberância occipital interna, dá inserção à foice do cerebelo e pode ser sulcada pelo seio occipital. A protuberância occipital interna situa-se junto da confluência dos seios.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-233-answer','quiz-neuro-ap1-233','Crista occipital interna',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-233-incorrect','quiz-neuro-ap1-233','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-234',unit_id,'quiz-topic-neuro-ap1','Que seio pode sulcar a crista occipital interna?',NULL,'O sulco sigmóide direito é habitualmente maior do que o esquerdo. A parte escamosa do occipital apresenta uma crista occipital interna mediana que se estende posteriormente do buraco magno até à protuberância occipital interna, dá inserção à foice do cerebelo e pode ser sulcada pelo <strong>seio occipital</strong>. A protuberância occipital interna situa-se junto da confluência dos seios.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
