INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-235-incorrect','quiz-neuro-ap1-235','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-236',unit_id,'quiz-topic-neuro-ap1','Que sulcos partem lateralmente da protuberância occipital interna?',NULL,'A protuberância occipital interna situa-se junto da confluência dos seios. <strong>De ambos os lados apresenta sulcos para os seios transversos, que curvam lateralmente com convexidade superior até aos ângulos mastoideus dos parietais.</strong> O sulco transverso é habitualmente mais profundo à direita, onde se continua com frequência com o seio sagital superior; à esquerda é frequentemente continuação do seio reto.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
